(()=>{
  'use strict';
  const API='https://data.superintelligencesg.org/directory/api/source-suggestions';
  const authForm=document.querySelector('#admin-auth'),keyInput=document.querySelector('#admin-key'),notice=document.querySelector('#notice'),workspace=document.querySelector('#workspace'),filter=document.querySelector('#status-filter'),refresh=document.querySelector('#refresh'),logout=document.querySelector('#logout'),cards=document.querySelector('#cards'),summary=document.querySelector('#queue-summary');
  let token='';
  const statuses=['received','in_review','accepted','rejected','resolved'];
  const canPublish=status=>['accepted','resolved'].includes(status);
  function message(text,type=''){notice.textContent=text;notice.className=`notice${type?' '+type:''}`}
  function safeHref(value){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}}
  function date(value){return value?new Date(Number(value)*1000).toLocaleString('en-SG',{dateStyle:'medium',timeStyle:'short'}):'—'}
  function requestOptions(){return {headers:{Authorization:`Bearer ${token}`},signal:AbortSignal.timeout(15000)}}
  async function readQueue(){refresh.disabled=true;message('Loading submissions…');try{const query=filter.value?`?status=${encodeURIComponent(filter.value)}&limit=100`:'?limit=100',response=await fetch(API+query,requestOptions()),data=await response.json().catch(()=>({}));if(response.status===401){logoutQueue();throw new Error('The management key was rejected.')}if(!response.ok)throw new Error(data.error||'The queue is temporarily unavailable.');render(data.submissions||[]);message('Queue refreshed.','success')}catch(error){if(token)message(error.message||'The queue is temporarily unavailable.','error')}finally{refresh.disabled=false}}
  function link(label,value){const href=safeHref(value);if(!href)return null;const a=document.createElement('a');a.href=href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label;return a}
  function selectField(value){const select=document.createElement('select');statuses.forEach(status=>{const option=document.createElement('option');option.value=status;option.textContent=status.replace('_',' ');option.selected=status===value;select.append(option)});return select}
  function render(items){cards.replaceChildren();summary.textContent=`${items.length} submission${items.length===1?'':'s'} shown`;if(!items.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='No submissions match this filter.';cards.append(empty);return}items.forEach(item=>{const card=document.createElement('article');card.className='card';const top=document.createElement('div');top.className='card-top';const heading=document.createElement('div');const h3=document.createElement('h3');h3.textContent=item.subject_name||'Untitled submission';heading.append(h3);const meta=document.createElement('div');meta.className='meta';meta.textContent=`${item.request_type||'request'} · received ${date(item.created_at)}`;heading.append(meta);const badge=document.createElement('span');badge.className='badge';badge.textContent=item.status||'received';top.append(heading,badge);card.append(top);const links=document.createElement('div');links.className='links';const subject=link('Subject website ↗',item.subject_url),source=link('Evidence source ↗',item.source_url);if(subject)links.append(subject);if(source)links.append(source);if(item.contact_email){const email=document.createElement('a');email.href=`mailto:${item.contact_email}`;email.textContent='Contact email ↗';links.append(email)}if(links.childNodes.length)card.append(links);const details=document.createElement('p');details.textContent=item.details||'';card.append(details);const review=document.createElement('div');review.className='review';const statusLabel=document.createElement('label');statusLabel.textContent='Decision';const status=selectField(item.status||'received');statusLabel.append(status);const noteLabel=document.createElement('label');noteLabel.textContent='Review note';const note=document.createElement('textarea');note.maxLength=2000;note.value=item.review_note||'';note.placeholder='What did you check or decide?';noteLabel.append(note);const summaryLabel=document.createElement('label');summaryLabel.className='full';summaryLabel.textContent='Public Changelog summary';const publicSummary=document.createElement('textarea');publicSummary.maxLength=500;publicSummary.value=item.public_summary||'';publicSummary.placeholder='Short factual description shown publicly after acceptance.';summaryLabel.append(publicSummary);const publishLabel=document.createElement('label');publishLabel.className='check full';const publish=document.createElement('input');publish.type='checkbox';publish.checked=Boolean(item.published_at);publish.disabled=!canPublish(status.value);const publishText=document.createElement('span');publishText.textContent='Publish this decision on the public Changelog';publishLabel.append(publish,publishText);const save=document.createElement('button');save.className='button';save.type='button';save.textContent='Save decision';status.addEventListener('change',()=>{publish.disabled=!canPublish(status.value);if(publish.disabled)publish.checked=false});save.addEventListener('click',()=>saveReview(item.id,status,note,publicSummary,publish,save));review.append(statusLabel,noteLabel,summaryLabel,publishLabel,save);const history=document.createElement('details');history.className='history';const historySummary=document.createElement('summary');historySummary.textContent='Review history';const historyList=document.createElement('div');historyList.className='history-list';history.append(historySummary,historyList);history.addEventListener('toggle',()=>{if(history.open&&!history.dataset.loaded)loadHistory(item.id,historyList,history)});review.append(history);card.append(review);cards.append(card)})}
  async function loadHistory(id,list,container){container.dataset.loaded='loading';try{const response=await fetch(`${API}/${encodeURIComponent(id)}/events`,requestOptions()),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Unable to load history.');list.replaceChildren();(data.events||[]).forEach(event=>{const row=document.createElement('div');row.className='history-item';const title=document.createElement('b');title.textContent=`${event.from_status} → ${event.to_status} · ${date(event.created_at)}`;const note=document.createElement('div');note.textContent=event.review_note||'No internal note.';row.append(title,note);if(event.publish_changelog){const published=document.createElement('div');published.textContent='Published on public Changelog';row.append(published)}list.append(row)});if(!data.events?.length)list.textContent='No review events yet.';container.dataset.loaded='true'}catch(error){list.textContent=error.message||'Unable to load history.';container.dataset.loaded='true'}}
  async function saveReview(id,status,note,publicSummary,publish,button){button.disabled=true;button.textContent='Saving…';try{const response=await fetch(`${API}/${encodeURIComponent(id)}`,{method:'PATCH',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({status:status.value,review_note:note.value,public_summary:publicSummary.value,publish_changelog:publish.checked}),signal:AbortSignal.timeout(15000)}),data=await response.json().catch(()=>({}));if(response.status===401){logoutQueue();throw new Error('The management key was rejected.')}if(!response.ok)throw new Error(data.error||'The decision could not be saved.');message(publish.checked?'Decision saved and published.':'Decision saved.','success');await readQueue()}catch(error){if(token)message(error.message||'The decision could not be saved.','error')}finally{button.disabled=false;button.textContent='Save decision'}}
  function logoutQueue(){token='';workspace.hidden=true;keyInput.value='';message('The key was cleared from this browser session.')}
  authForm.addEventListener('submit',async event=>{event.preventDefault();const value=keyInput.value.trim();if(!value)return;token=value;await readQueue();if(token)workspace.hidden=false});filter.addEventListener('change',readQueue);refresh.addEventListener('click',readQueue);logout.addEventListener('click',logoutQueue);
})();
